use std :: sync :: Arc ; use colored :: Colorize ; use forge_api :: API ; use forge_config :: { Update , UpdateFrequency } ; use forge_select :: ForgeWidget ; use forge_tracker :: VERSION ; use update_informer :: { Check , Version , registry } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Runs the official installation script to update Forge, failing silently."] # [doc = " When `auto_update` is true, exits immediately after a successful update"] # [doc = " without prompting the user."] async fn execute_update_command (api : Arc < impl API > , auto_update : bool) { let output = api . execute_shell_command_raw ("curl -fsSL https://forgecode.dev/cli | sh") . await ; match output { Err (err) => { let _ = send_update_failure_event (& format ! ("Auto update failed {err}")) . await ; } Ok (output) => { if output . success () { let should_exit = if auto_update { true } else { let answer = forge_select :: ForgeWidget :: confirm ("You need to close forge to complete update. Do you want to close it now?" ,) . with_default (true) . prompt () ; answer . unwrap_or_default () . unwrap_or_default () } ; if should_exit { std :: process :: exit (0) ; } } else { let exit_output = match output . code () { Some (code) => format ! ("Process exited with code: {code}") , None => "Process exited without code" . to_string () , } ; let _ = send_update_failure_event (& format ! ("Auto update failed, {exit_output}" ,)) . await ; } } } }